"""Promote first checked GPU overlay translation; retain full-game limits."""
from datetime import datetime,timezone
import json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(p):return json.loads(p.read_text())
def save(p,x):p.write_text(json.dumps(x,indent=2)+'\n')

def main():
    now=datetime.now(timezone.utc).isoformat();s=Path(read(ROOT/'projects/black-ice-white-noise/analysis/current-session.json')['directory'])
    checked=read(ROOT/'verification/biwn-sprite-decode-checks.json');local=read(ROOT/'verification/biwn-gpu-sprite-local-review.json');assert checked['GPU_cases']==244 and checked['actual_asset_cases']==61 and checked['host_guard_cases']==14
    assert local['status']=='coordinator_reviewed_run_lengths_rejected_correlated_drafts'
    validation=read(s/'boot-slice-validation.json');assert validation['portable_C_component_count']==21
    validation.update(portable_C_component_count=22,processor_component_counts={'CPU':21,'GPU':1},latest_aggregate_update=now,
        component_count_scope='21earlierCPUcomponents plus GPU4B00sprite-word decoder. IsolatedGPUoverlay checked against pinned emulator; not yet linked into the inventorybackend. Rasterization, displaycolors and full reconstructedgame unfinished.',nextstage_GPU_sprite_decoder_C=checked)
    save(s/'boot-slice-validation.json',validation);subprocess.run([str(ROOT/'.venv/bin/python'),str(ROOT/'scripts/summarize_biwn_checks.py')],check=True)
    game='22 checked portable C components: 21 CPU components and the first GPU overlay translation. Sprite decoder matches original GPU execution in 244 cases: all 61 frames of one actual asset container, 183 synthetic cases and 14 host guards. Whole2MBRAM, external read-address/width/order shapes, write values/order and key final GPUregisters match. Original readwatchvalues are placeholders. Raw16bit sprite words are reconstructed; decoder is not yet linked into the inventorybackend, and full rasterization/game remains unfinished.'
    frontend='Latest read-only inventory evidence includes standalone GPUdecoder facts and exact run-length examples. Diagnostic silhouettes are generated from checked C output, without color assumptions. Native Chat adoption remains unverified while locked; API/role exchanges saved for post review.'
    next_work='Connect the GPU sprite decoder to the reconstructed inventory backend, reconstruct drawing/text rasterization and compare a rebuilt inventory frame. Broaden game integration and local-model quality evaluation; verify nativeChat refresh when accessible. Advertising trained pilot remains loadable/experimental with source and teaching evaluation ongoing. Full goal active incomplete.'
    models=json.loads(subprocess.check_output([str(Path.home()/'.lmstudio/bin/lms'),'ps','--json'],cwd=Path.home()/'.lmstudio',text=True));assert len(models)==1 and models[0]['status']=='idle'
    evidence=['verification/biwn-sprite-decode-checks.json','verification/biwn-gpu-sprite-local-review.json',str((s/'gpu-sprite-overlay/mapping.json').relative_to(ROOT)),'artifacts/decoded-sprites/provenance.json']
    for name in ['setup-status.json','current-runtime-state.json','everyday-inference.json','requirements-audit.json']:
        p=ROOT/'verification'/name;x=read(p)
        if name=='setup-status.json':x.update(updated_at_utc=now,game_work=game,frontend=frontend,pending=next_work)
        elif name=='current-runtime-state.json':x.update(recorded_at=now,models=models,model_state_refreshed_at=now,decomp_progress=game,
            local_inference_jobs='Two localGPUdrafts terminal; all run-length claims rejected. Usual27Bidle. No backgroundtraining/inference claimed.',emulator_jobs='244isolatedGPUoracle processes terminal,0CPU/DSP/gameframes in measured phase; originalpinnedcore unchanged. No new whole-game replay.',visible_chat=frontend,MCP_updated_evidence='22components, including standaloneGPU spritewords and checkedrunlengths. NativeChat adoption unverified.')
        elif name=='everyday-inference.json':x.update(updated_at=now,model=models,model_state_refreshed_at=now,frontend=frontend,latest_GPU_sprite_review=str(ROOT/evidence[0]),latest_local_game_roles=str(ROOT/evidence[1]))
        else:
            x.update(recorded_at_utc=now,previous_goal_turn_classification=x['this_goal_turn_classification'],this_goal_turn_classification='progress: GPUoverlay608byte mapping/classification, fullCdecoder244GPUcases/14guards and61realassets match, diagnosticpreview and rejectedcorrelated runlengthdrafts',next_safe_work=next_work)
            for item in x['requirements']:
                if 'decompilation test'in item['requirement']:item['state']=game;item['evidence']=list(dict.fromkeys(item['evidence']+evidence))
                elif 'Multiagent game'in item['requirement']:item['state']+=' GPUanalyst/reviewer returned wrongrunranges and copied eachother; coordinator rejected contracts against originalGPUoracle outputs.';item['evidence']=list(dict.fromkeys(item['evidence']+[evidence[1]]))
            x['post_review_evidence'].update({Path(e).name:str(ROOT/e)for e in evidence})
        save(p,x)
    config=read(ROOT/'config.json');config['chat_frontend']['game']['status']=game+' '+frontend;save(ROOT/'config.json',config)
    intake=read(ROOT/'corpus/game/project-intake.json');intake.update(latest_checked_at=now,latest_checked_status=game,latest_GPU_sprite_check=str(ROOT/evidence[0]));save(ROOT/'corpus/game/project-intake.json',intake)
    p=ROOT/'projects/black-ice-white-noise/restoration/READ ME.txt';p.write_text(p.read_text()+'\nFIRST GPU OVERLAY TRANSLATION — '+now+'\n'+game+'\nFiles: biwn_sprite_decode.c/.h. Reproduce: .venv/bin/python scripts/check_biwn_sprite_decode.py. Oracle runs preservedGPUoverlay in pinnedcore afterprivateRAMload; no gameframes or corechanges. Literal trailingprefetch, signedorigins, zero-sized images and runovershoot preserved. Hostreadlimits/errors retainpriorwrites. Source mapping/code-data tables: '+str(s/'gpu-sprite-overlay')+'\n')
    export=Path(read(s/'drawing-volatile-summary.json')['directory'])/'export'
    (ROOT/'CURRENT DECOMPILATION.txt').write_text('BLACK ICE WHITE NOISE — CURRENT RECONSTRUCTION\n\nFull rebuilt game: unfinished. Original game observed separately in an assisted emulator.\n\nCHECKED C\n'+game+'\n\nGPU decoder source:\n'+str(ROOT/'projects/black-ice-white-noise/restoration/biwn_sprite_decode.c')+'\nGPU checks:\n'+str(ROOT/evidence[0])+'\nRaw decoded words and diagnostic preview:\n'+str(ROOT/'artifacts/decoded-sprites')+'\n\nCPU PIPELINE\n54combinedCPUcases and nine original-game intervals/5,812drawing-text wordwrites checked previously. The new GPUdecoder remains a separate component; complete inventoryrasterization is unfinished.\n\nAPPROXIMATE CPU EXPORT\n18,306 decoded CPUinstructions and206entry candidates. No CPUinstructions overlap the newly classified GPUoverlayheader/body. AutomaticC remains approximate.\n'+str(export/'decompiled.c')+'\n\nAll exact local prompts/responses and errors: POST REVIEW.txt.\n')
    p=ROOT/'START HERE.txt';text=p.read_text().replace('Game: 21 isolated C components checked.','Game: 22 isolated C components checked (21 CPU and one GPU).').replace('GPU processing and rasterization still need reconstruction; the complete rebuilt game is unfinished.','The standalone GPU sprite decoder now produces checked raw image words. It still needs connection to the inventory backend, and rasterization/the complete rebuilt game remain unfinished.');p.write_text(text)
    p=ROOT/'POST REVIEW.txt';p.write_text(p.read_text()+'\nGPU4B00 SPRITE DECODER / RAW IMAGE OUTPUT — '+now+'\n'+game+'\nWHO DID WHAT: Codex mapped CPU4B00header to608byteGPUoverlayF03240..F034A0 and classified two pointertables/padding as data. ExistingCPUexport has0instructions overlappingheader/body, so no CPUprojectedit required. Codex read originalAtariJTRM pages39/54/55/57 for delayslot, shift andSUBQT semantics; archivedprimaryPDF/hash. Codex wrote high-levelCdecoder and isolatedoriginalGPUoracle, compiled/tested244cases/14guards and compared wholeRAM/busshapes/writevalues/finalregisters. OriginalGPUreadwatchvalues remainzero placeholders; only addresses/width/order and actualwritevalues compared. CompletionDIVCTRLsentinelA5A50001clears0. No corepatches or gameframes in oracle phase. Codex generated and visually inspected six diagnosticnonzero-word silhouettes, not displaycolors or a rebuiltframe. Initialpreview attempts had else0 syntax error then missingPillow; neither producedoutput. Used bundledimageruntime without alteringmodelvenv.\nActual local27Banalyst19.53seconds/reviewer20.30seconds both gave wrongthree runranges; reviewer copiedanalyst byte-exactly. Bothcontracts rejected. Correctzero2..17,repeatedpalette2..9,literal1..16; maxsingle-runoriginalGPUwrites34/18/32bytes. No localmodelcode accepted and no weighttraining thisturn.\nExact prompts/responses:\n'+str(Path(local['directory'])/'prompts-and-responses.txt')+'\nCoordinatoraudit:\n'+str(ROOT/evidence[1])+'\nCPU/GPU mapping:\n'+str(ROOT/evidence[2])+'\nPrimaryreference:\nhttps://www.jagware.org/jag_uploads/dev/glenn_bruner_atarishowroom/pdf/Jag_v8.pdf\nPDFSHA256:63aacc7fc7b56f7561731b2462c8ae2c6a4888ec12a2e74a936eef11512b5d4e\nGPUfixtures:\n'+checked['directory']+'\nDiagnosticpreview:\n'+str(ROOT/'artifacts/decoded-sprites/sprite-silhouettes.png')+'\n'+next_work+'\n')
    install=subprocess.run([str(ROOT/'.venv/bin/python'),str(ROOT/'scripts/install_chat_runtime.py')],check=True,capture_output=True,text=True);(ROOT/'verification/GPU-sprite-runtime-install.txt').write_text(install.stdout+'\n'+install.stderr)
    save(ROOT/'verification/GPU-sprite-checkpoint.json',{'recorded_at':now,'backup':read(ROOT/'verification/GPU-sprite-checkpoint-backup.json')['directory'],'models':models,'portable_components':22,'CPU_components':21,'GPU_components':1,'GPU_cases':244,'actual_asset_frames':61,'GPU_host_guards':14,'full_goal_status':'active incomplete','known_compute_jobs':'terminal','evidence':evidence,'fresh_evidence_snapshot_installed':True,'native_Chat_adoption':'unverified while locked','next_work':next_work})
    print(json.dumps({'components':22,'CPU':21,'GPU':1,'GPUcases':244,'actualframes':61,'installed':True}),flush=True)

if __name__=='__main__':main()
